@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap');
:root{--ink:#24382e;--muted:#7a877b;--green:#2d6847;--green2:#3e8054;--cream:#f6f5eb;--paper:#fffef8;--line:#e6e8d9;--gold:#dfaa4a}*{box-sizing:border-box}body{margin:0;background:#e9eee2;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;padding:24px 20px;display:flex;justify-content:center;align-items:flex-start}.game-shell{width:min(1280px,100%);background:var(--cream);border:1px solid #dfe5d6;border-radius:20px;overflow:hidden;box-shadow:0 20px 60px #253c2c1c}.topbar{height:90px;display:flex;align-items:center;padding:0 27px;background:#fffef9;border-bottom:1px solid var(--line);gap:30px}.brand{display:flex;align-items:center;gap:12px;min-width:260px}.brand-mark{width:43px;height:43px;background:#e7f1df;color:#4b8a52;border-radius:14px;display:grid;place-items:center;font-size:26px}.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.55px;color:#8a9989}.brand h1{font:700 23px Fraunces,serif;letter-spacing:-.6px;margin:1px 0 0}.brand h1 span{color:#5d8b5a}.day-card{display:flex;align-items:center;gap:10px;padding-left:28px;border-left:1px solid var(--line);min-width:190px}.sun-icon{font-size:22px;color:#e3a739;width:31px;height:31px;border-radius:50%;background:#fff3d5;display:grid;place-items:center}.day-card small,.resource small{display:block;color:#8c998b;font-size:9px;font-weight:800;letter-spacing:1px}.day-card strong{font:600 14px Fraunces,serif;display:block;margin-top:3px}.day-card i{font-style:normal;color:#a8b19f}.resources{display:flex;gap:26px;margin-left:auto}.resource{display:flex;align-items:center;gap:8px;min-width:65px}.resource-icon{width:30px;height:30px;border-radius:10px;display:grid;place-items:center;font-weight:800}.coin{background:#fff2d6;color:#c18a2e;font-size:16px}.seed{background:#e8f2e3;color:#4d8c50}.heart{background:#fbe9e4;color:#dd7662}.resource strong{font-size:14px;display:block;margin-top:2px}.play-area{padding:21px 24px 17px;display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:19px}.scene-wrap{min-width:0}.scene-heading{height:34px;display:flex;align-items:flex-start;justify-content:space-between;padding:0 4px;color:#687b69;font-size:11px;font-weight:700}.scene-heading>div:first-child{display:flex;align-items:center;gap:8px}.live-dot{width:7px;height:7px;border-radius:100%;background:#76a865;box-shadow:0 0 0 3px #76a86520}.weather{font-size:10px;color:#93a094;font-weight:600}.weather span{font-size:14px;color:#90a9ac}.weather b{padding:0 5px;color:#c5cabb}.canvas-frame{position:relative;border:5px solid #e8ebdd;border-radius:13px;overflow:hidden;background:#8eb879;box-shadow:inset 0 0 0 1px #ffffff55;line-height:0}canvas{width:100%;height:auto;display:block;image-rendering:pixelated;touch-action:none}.canvas-tip{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);white-space:nowrap;background:#213b2bd9;color:#eff4e8;padding:8px 13px;border-radius:9px;font-size:10px;font-weight:600;line-height:1;pointer-events:none;opacity:.92}.canvas-tip b{color:#a6d18b;padding:0 5px}.side-panel{display:flex;flex-direction:column;gap:11px}.panel-card{background:var(--paper);border:1px solid #e6e8dd;border-radius:13px;padding:14px 15px}.section-label{font-size:9px;font-weight:800;color:#879386;letter-spacing:1.15px;display:flex;justify-content:space-between}.section-label span{color:#d4a449;font-size:13px}.task-card h2{font:600 17px Fraunces,serif;margin:12px 0 5px}.task-card p{color:#829082;font-size:10px;line-height:1.5;margin:0 0 12px}.progress-track{height:5px;border-radius:8px;background:#edf0e7;overflow:hidden}.progress-fill{height:100%;width:0;background:linear-gradient(90deg,#79ad67,#b0ca6f);border-radius:8px;transition:width .25s}.progress-caption{display:flex;justify-content:space-between;margin-top:7px;color:#869283;font-size:9px;font-weight:700}.progress-caption span:last-child{color:#bc9560}.tool-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin-top:11px}.tool-button{border:1px solid #e7e9de;background:#fcfcf6;border-radius:9px;height:49px;cursor:pointer;color:#546451;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;transition:.16s;position:relative}.tool-button:hover{border-color:#9cbd8d;transform:translateY(-1px)}.tool-button.active{background:#e9f2e3;border-color:#76a96a;color:#356a42;box-shadow:0 0 0 1px #76a96a22}.tool-button .glyph{font-size:18px;line-height:19px}.tool-button small{font-size:8px;font-weight:700}.tool-button .key{position:absolute;top:3px;right:4px;font-size:7px;color:#a5ae9f}.tool-hint{margin-top:9px;font-size:9px;color:#8b9787;line-height:1.4;min-height:12px}.night-card{padding-bottom:12px}.night-info{display:flex;gap:10px;margin-top:12px;align-items:center}.tower-illustration{flex:0 0 39px;height:39px;border-radius:12px;background:#edf3e6;color:#568452;font-size:28px;display:grid;place-items:center;position:relative;line-height:1}.tower-illustration span{position:absolute;right:3px;top:1px;font-size:10px;color:#dfaf4f}.night-info strong{font-size:10px}.night-info p{margin:4px 0 0;color:#899589;font-size:9px;line-height:1.4}.night-stats{border-top:1px solid #eef0e7;margin-top:11px;padding-top:9px;display:flex;justify-content:space-between;color:#929d90;font-size:8px;font-weight:800;letter-spacing:.5px}.night-stats b{color:#4d684b;font-size:10px;margin-left:4px}.primary-button{border:0;border-radius:11px;background:#3e7850;color:#fffdf6;font:700 12px 'DM Sans',sans-serif;padding:13px 15px;cursor:pointer;box-shadow:0 3px 0 #2c5e3d;transition:.15s;display:flex;align-items:center;justify-content:center;gap:8px}.primary-button:hover{background:#48865a;transform:translateY(-1px)}.primary-button:active{transform:translateY(1px);box-shadow:0 1px 0 #2c5e3d}.primary-button kbd{font:600 8px 'DM Sans',sans-serif;color:#d0e4cd;background:#ffffff20;border:1px solid #ffffff30;border-radius:4px;padding:3px 5px;margin-left:auto}.save-note{text-align:center;color:#99a293;font-size:9px;margin-top:auto;padding-top:3px}.save-note span{color:#79a66b;padding-right:4px}.footer{height:40px;padding:0 29px;display:flex;align-items:center;justify-content:space-between;background:#f0f1e7;border-top:1px solid #e6e8db;font-size:9px;color:#929c8c}.footer b{letter-spacing:1px;color:#748571;font-size:8px}.footer i{font-style:normal;padding:0 4px;color:#c3c9b9}.toast{position:fixed;left:50%;top:20px;transform:translate(-50%,-20px);padding:11px 18px;background:#253d2e;color:#fff;border-radius:10px;font-size:12px;font-weight:600;box-shadow:0 8px 25px #182b1e36;opacity:0;pointer-events:none;transition:.22s;z-index:5}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#16251c99;display:grid;place-items:center;z-index:10;padding:18px}.modal-backdrop[hidden]{display:none}.modal-card{background:#fffef8;border-radius:20px;padding:34px 32px;width:min(380px,100%);text-align:center;box-shadow:0 24px 80px #12211855}.modal-icon{margin:0 auto 15px;width:54px;height:54px;border-radius:17px;background:#edf4e5;display:grid;place-items:center;color:#65935a;font-size:28px}.modal-card h2{font:700 25px Fraunces,serif;margin:8px 0}.modal-card>p:not(.eyebrow){font-size:12px;line-height:1.6;color:#829082;margin:0 0 22px}.modal-card .primary-button{width:100%}.modal-card .eyebrow{margin:0}
@media(max-width:900px){body{padding:10px}.play-area{grid-template-columns:minmax(0,1fr) 230px;padding:14px;gap:12px}.topbar{padding:0 17px;gap:18px}.brand{min-width:220px}.resources{gap:12px}.footer{padding:0 17px}}
@media(max-width:700px){body{padding:0;background:var(--cream)}.game-shell{border:0;border-radius:0;box-shadow:none}.topbar{height:auto;min-height:72px;padding:10px 12px;gap:9px;flex-wrap:wrap}.brand{min-width:0;flex:1;gap:8px}.brand-mark{width:36px;height:36px;font-size:22px;border-radius:11px}.brand h1{font-size:19px}.brand .eyebrow{font-size:7px}.day-card{min-width:0;border:0;padding-left:5px;gap:6px}.sun-icon{height:27px;width:27px;font-size:17px}.day-card small{font-size:8px}.day-card strong{font-size:12px}.resources{order:3;width:100%;justify-content:space-around;border-top:1px solid var(--line);padding-top:8px;gap:0}.resource{min-width:0}.resource-icon{height:25px;width:25px;border-radius:8px}.resource small{font-size:8px}.resource strong{font-size:12px}.play-area{display:flex;flex-direction:column;padding:11px 9px;gap:10px}.scene-heading{height:27px;padding:0 3px}.canvas-frame{border-width:3px;border-radius:9px}.canvas-tip{bottom:5px;padding:6px 8px;font-size:8px}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:8px}.panel-card{padding:11px}.task-card{grid-column:1/-1}.task-card h2{font-size:15px;margin-top:8px}.task-card p{font-size:9px;margin-bottom:8px}.tool-grid{gap:3px;margin-top:8px}.tool-button{height:45px}.tool-button .glyph{font-size:16px}.tool-button small{font-size:7px}.tool-hint{font-size:8px;margin-top:6px}.night-card{grid-column:1/2}.night-info{gap:6px}.tower-illustration{flex-basis:32px;height:32px;font-size:23px}.night-info strong{font-size:9px}.night-info p{font-size:8px}.primary-button{grid-column:2/3;align-self:stretch;font-size:11px;padding:10px}.save-note{grid-column:1/-1;padding:1px 0 2px}.footer{height:auto;min-height:34px;padding:8px 12px;font-size:8px;gap:8px}.footer span:last-child{text-align:right}.footer b{font-size:7px}}
@media(max-width:380px){.day-card{display:none}.side-panel{grid-template-columns:1fr 1fr}.night-info p{font-size:7px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 576, TS = 48, COLS = 20, ROWS = 12;
  const $ = (id) => document.getElementById(id);
  const ui = {gold:$('goldLabel'),seeds:$('seedLabel'),hp:$('hpLabel'),day:$('dayLabel'),phase:$('phaseLabel'),icon:$('phaseIcon'),scene:$('sceneTitle'),mission:$('missionTitle'),missionText:$('missionText'),progress:$('progressFill'),progressText:$('progressText'),countdown:$('phaseCountdown'),wave:$('waveLabel'),enemies:$('enemyLabel'),button:$('phaseButton'),tip:$('toolHint'),toast:$('toast'),modal:$('modal')};
  const tools = [
    {id:'hoe',name:'Hoe',glyph:'⌁',hint:'Till an empty patch in the garden.'},
    {id:'seed',name:'Seeds',glyph:'✿',hint:'Plant a seed on a tilled patch.'},
    {id:'water',name:'Water',glyph:'♧',hint:'Water a planted crop to help it grow.'},
    {id:'harvest',name:'Harvest',glyph:'✂',hint:'Gather crops when they are ready.'},
    {id:'tower',name:'Turret',glyph:'⌂',hint:'Build on grass for 12 gold. It fires at night.'}
  ];
  const path = [[19,2],[19,3],[18,3],[17,3],[16,3],[16,4],[16,5],[15,5],[14,5],[14,6],[13,6],[13,7],[13,8],[12,8],[11,8],[10,8],[9,8],[9,9],[8,9],[7,9],[6,9],[5,9]];
  const pathSet = new Set(path.map(([x,y])=>`${x},${y}`));
  const route = path.map(([x,y])=>({x:x+.5,y:y+.5}));
  const garden = (x,y) => x>=1&&x<=8&&y>=1&&y<=8;
  const state = {day:1,phase:'day',gold:24,seeds:5,hp:10,maxHp:10,tool:'hoe',crops:new Map(),tilled:new Set(),towers:[],enemies:[],shots:[],player:{x:5.5,y:6.5,face:{x:0,y:1}},hover:null,dayTime:0,dayLength:72,spawned:0,waveTotal:0,spawnTimer:0,nightAge:0,elapsed:0,toastTimer:0,modalMode:'',lastTime:0,accum:0,dead:false};
  const toolButtons = new Map();
  const toolGrid = $('toolGrid');
  tools.forEach((t,i)=>{const b=document.createElement('button');b.type='button';b.className='tool-button';b.dataset.tool=t.id;b.setAttribute('aria-label',`${i+1}: ${t.name}`);b.innerHTML=`<span class="key">${i+1}</span><span class="glyph">${t.glyph}</span><small>${t.name}</small>`;b.addEventListener('click',()=>selectTool(t.id));toolGrid.appendChild(b);toolButtons.set(t.id,b);});
  let toastTimer;
  function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100);}
  function selectTool(id){state.tool=id;toolButtons.forEach((b,k)=>b.classList.toggle('active',k===id));const tool=tools.find(t=>t.id===id);ui.tip.textContent=tool.hint;}
  function tileKey(x,y){return `${x},${y}`;}
  function isPath(x,y){return pathSet.has(tileKey(x,y));}
  function tileAtEvent(e){const r=canvas.getBoundingClientRect();return {x:Math.floor((e.clientX-r.left)*W/r.width/TS),y:Math.floor((e.clientY-r.top)*H/r.height/TS)};}
  function useTile(x,y){if(x<0||x>=COLS||y<0||y>=ROWS||state.dead)return;const key=tileKey(x,y), crop=state.crops.get(key), tool=state.tool;
    if(tool==='hoe'){if(state.phase!=='day'){toast('The garden can wait until morning.');return;}if(!garden(x,y)||isPath(x,y)||crop){toast('Choose an empty patch inside the garden.');return;}if(state.tilled.has(key)){toast('This patch is ready for a seed.');return;}state.tilled.add(key);toast('Fresh earth, ready for planting!');}
    else if(tool==='seed'){if(state.phase!=='day'){toast('Planting is a daytime job.');return;}if(!state.tilled.has(key)||crop){toast('Till a patch first, then plant here.');return;}if(state.seeds<1){toast('You are out of seeds.');return;}state.seeds--;state.crops.set(key,{growth:0,watered:false});toast('A little seed tucked into the soil.');}
    else if(tool==='water'){if(state.phase!=='day'){toast('Water the crops in the morning.');return;}if(!crop){toast('There is no crop to water here.');return;}if(crop.watered){toast('This crop has had its drink today.');return;}crop.watered=true;toast('Your crop looks refreshed.');}
    else if(tool==='harvest'){if(!crop||crop.growth<3){toast('Not quite ripe yet.');return;}state.crops.delete(key);state.tilled.add(key);state.gold+=8;state.seeds+=1;toast('Harvested! +8 gold and a seed.');}
    else if(tool==='tower'){if(state.towers.some(t=>t.x===x+.5&&t.y===y+.5)){toast('There is already a turret here.');return;}if(isPath(x,y)||garden(x,y)||isBarnTile(x,y)){toast('Turrets need a clear patch of meadow.');return;}if(state.gold<12){toast('A sprout turret costs 12 gold.');return;}state.gold-=12;state.towers.push({x:x+.5,y:y+.5,cooldown:.2,flash:0});toast('Sprout turret planted. It will guard your barn!');}
    updateUI();
  }
  function isBarnTile(x,y){return x>=2&&x<=4&&y>=9&&y<=10;}
  function tryMove(dx,dy){if(state.dead)return;const nx=Math.max(.5,Math.min(COLS-.5,state.player.x+dx)),ny=Math.max(.5,Math.min(ROWS-.5,state.player.y+dy));state.player.x=nx;state.player.y=ny;state.player.face={x:dx,y:dy};}
  function useFacing(){const p=state.player;useTile(Math.floor(p.x+p.face.x),Math.floor(p.y+p.face.y));}
  canvas.addEventListener('pointermove',e=>{state.hover=tileAtEvent(e);});canvas.addEventListener('pointerleave',()=>state.hover=null);canvas.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;const p=tileAtEvent(e);useTile(p.x,p.y);});
  window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(key==='1'||key==='2'||key==='3'||key==='4'||key==='5')selectTool(tools[Number(key)-1].id);else if(key==='w'||key==='arrowup')tryMove(0,-1);else if(key==='s'||key==='arrowdown')tryMove(0,1);else if(key==='a'||key==='arrowleft')tryMove(-1,0);else if(key==='d'||key==='arrowright')tryMove(1,0);else if(key===' ')useFacing();else if(key==='enter'){if(!ui.modal.hidden)modalAction();else if(state.phase==='day')startNight();}});
  ui.button.addEventListener('click',()=>state.phase==='day'?startNight():toast('Your turrets are on night watch!'));
  $('modalButton').addEventListener('click',modalAction);
  function startNight(){if(state.phase!=='day'||state.dead)return;state.phase='night';state.spawned=0;state.waveTotal=7+state.day*2;state.spawnTimer=.45;state.nightAge=0;state.enemies=[];state.shots=[];state.towers.forEach(t=>t.cooldown=.25);ui.scene.textContent='The lanterns are coming on';toast('Night falls. Protect the barn!');updateUI();}
  function finishNight(){if(state.dead)return;state.gold+=Math.max(2,Math.floor(state.waveTotal/2));showModal('win');}
  function dawn(){state.day++;state.phase='day';state.dayTime=0;state.enemies=[];state.shots=[];state.towers.forEach(t=>t.cooldown=.2);for(const crop of state.crops.values()){if(crop.watered)crop.growth=Math.min(3,crop.growth+1);crop.watered=false;}state.seeds+=2;state.player.x=5.5;state.player.y=6.5;state.player.face={x:0,y:1};ui.scene.textContent='The farm wakes with the sun';updateUI();toast('A new morning! +2 seeds.');}
  function showModal(mode){state.modalMode=mode;const titles={win:['✦','NIGHT CLEARED','The barn is safe!','The monsters scattered into the woods. Your crops have had a chance to grow.','Welcome the morning'],lose:['♡','THE NIGHT GOT TOO WILD','The barn needs mending','The monsters broke through. Start a fresh farm and try a few more turrets.','Start a new farm']};const a=titles[mode];$('modalIcon').textContent=a[0];$('modalEyebrow').textContent=a[1];$('modalTitle').textContent=a[2];$('modalText').textContent=a[3];$('modalButton').innerHTML=`${a[4]} <span>→</span>`;ui.modal.hidden=false;}
  function modalAction(){ui.modal.hidden=true;if(state.modalMode==='win')dawn();else if(state.modalMode==='lose')resetGame();state.modalMode='';}
  function resetGame(){state.day=1;state.phase='day';state.gold=24;state.seeds=5;state.hp=10;state.towers=[];state.crops.clear();state.tilled.clear();state.enemies=[];state.shots=[];state.dead=false;state.dayTime=0;state.player.x=5.5;state.player.y=6.5;ui.scene.textContent='A bright new morning';updateUI();}
  function updateUI(){const night=state.phase==='night';ui.gold.textContent=state.gold;ui.seeds.textContent=state.seeds;ui.hp.textContent=`${state.hp} / ${state.maxHp}`;ui.day.innerHTML=`Day ${state.day} <i>·</i> Spring`;ui.phase.textContent=night?'NIGHT WATCH':'DAYTIME';ui.icon.textContent=night?'☾':'☀';ui.icon.style.color=night?'#8795d6':'#e3a739';ui.icon.style.background=night?'#eaebfa':'#fff3d5';ui.button.innerHTML=night?'<span>☾</span> Night watch in progress <kbd>● LIVE</kbd>':'<span>☀</span> Finish the day <kbd>Enter</kbd>';ui.button.disabled=night;ui.wave.textContent=state.day;ui.enemies.textContent=state.enemies.length;const ready=[...state.crops.values()].filter(c=>c.growth>=3).length;const planted=state.crops.size;const done=Math.min(3,planted);ui.progress.style.width=`${done/3*100}%`;ui.progressText.textContent=`${done} / 3 crops`;if(planted>=3){ui.mission.textContent=ready?'Harvest your ripe crop':'Keep your crops growing';ui.missionText.textContent=ready?`${ready} crop${ready>1?'s are':' is'} ready to harvest. Turn harvests into gold and seeds.`:'Water your crops each morning and keep the barn protected after dark.';}else{ui.mission.textContent='Plant the first seeds';ui.missionText.textContent='Till a patch, plant seeds, and give them a drink before dusk.';}if(night){ui.countdown.textContent=`${state.enemies.length} ON THE PATH`;ui.countdown.style.color='#7880bb';}else{const left=Math.max(0,Math.ceil(state.dayLength-state.dayTime));ui.countdown.textContent=`DUSK IN ${left}s`;ui.countdown.style.color='#bc9560';}}
  const rand=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);};
  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
  function drawTile(x,y){const n=rand(x*17+y*73),base=(x+y)%2?'#91bd7c':'#8ab675';ctx.fillStyle=base;ctx.fillRect(x*TS,y*TS,TS,TS);ctx.fillStyle=n>.5?'#a7c887':'#78a96c';ctx.globalAlpha=.22;ctx.fillRect(x*TS+4+rand(x+y*8)*31,y*TS+5+rand(y+x*5)*32,2,2);ctx.globalAlpha=1;if((x*13+y*7)%29===2&&!garden(x,y)&&!isPath(x,y)&&!isBarnTile(x,y)){ctx.fillStyle='#d9df91';ctx.fillRect(x*TS+14,y*TS+15,3,3);ctx.fillStyle='#f6e8ac';ctx.fillRect(x*TS+15,y*TS+13,2,2);}}
  function drawPath(){for(const [x,y] of path){const px=x*TS,py=y*TS;ctx.fillStyle=(x+y)%2?'#c3ad7d':'#ccb887';ctx.fillRect(px,py,TS,TS);ctx.fillStyle='#d9c99e';ctx.globalAlpha=.55;for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(px+6+rand(x*4+y+i)*36,py+5+rand(i+x+y*2)*37,2,1.3,0,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}}
  function drawGarden(){ctx.fillStyle='#6b9b61';ctx.fillRect(TS-4,TS-4,8*TS+8,8*TS+8);ctx.fillStyle='#adca85';ctx.fillRect(TS,TS,8*TS,8*TS);for(let y=1;y<=8;y++)for(let x=1;x<=8;x++){const px=x*TS,py=y*TS;ctx.fillStyle=(x+y)%2?'#a9c77f':'#a2c178';ctx.fillRect(px,py,TS,TS);ctx.fillStyle='#bad190';ctx.fillRect(px+3,py+3,42,1);if(state.tilled.has(tileKey(x,y))){ctx.fillStyle='#916844';ctx.fillRect(px+4,py+5,40,38);ctx.fillStyle='#a77a4e';for(let j=0;j<4;j++)ctx.fillRect(px+7,py+9+j*9,34,2);ctx.fillStyle='#805b3d';ctx.fillRect(px+6,py+41,36,2);const crop=state.crops.get(tileKey(x,y));if(crop)drawCrop(px+24,py+25,crop);}}}
  function drawCrop(cx,cy,crop){const stages=['#9d7544','#6c9d4f','#4f884c','#4f8d48'];const stage=Math.min(3,crop.growth);ctx.fillStyle='#765739';ctx.fillRect(cx-1,cy+4,3,9);if(stage===0){ctx.fillStyle='#83a647';ctx.fillRect(cx-5,cy+1,4,3);ctx.fillRect(cx+1,cy-1,4,3);ctx.fillStyle='#d0b06d';ctx.fillRect(cx-2,cy+2,4,3);}else{const size=[0,5,8,11][stage];ctx.fillStyle=stages[stage];ctx.fillRect(cx-size/2,cy-size/2,size,size);ctx.fillRect(cx-size,cy-3,size/2+1,3);ctx.fillRect(cx+2,cy-size,size/2,3);ctx.fillStyle='#b8d56b';ctx.fillRect(cx-5,cy-size+2,3,2);if(stage===3){ctx.fillStyle='#f0c858';ctx.fillRect(cx-3,cy-7,5,5);ctx.fillStyle='#fff0a1';ctx.fillRect(cx-2,cy-6,2,2);}}if(crop.watered){ctx.fillStyle='#94d5e6';ctx.beginPath();ctx.ellipse(cx+12,cy+13,2,3,0,0,Math.PI*2);ctx.fill();}}
  function drawPond(){ctx.fillStyle='#709e8f';ctx.fillRect(-6,-6,3*TS+10,3*TS+10);ctx.fillStyle='#83b6aa';ctx.beginPath();ctx.ellipse(39,44,74,55,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a4cec0';ctx.beginPath();ctx.ellipse(36,38,53,32,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5e2b2';ctx.fillRect(20,25,22,2);ctx.fillRect(61,56,16,2);ctx.fillStyle='#d0c382';ctx.fillRect(90,85,11,8);ctx.fillRect(118,109,9,7);}
  function drawBarn(){const x=2*TS,y=9*TS;ctx.fillStyle='#6f5741';ctx.fillRect(x-4,y+38,3*TS+8,2*TS-31);ctx.fillStyle='#d9c998';ctx.fillRect(x-7,y+35,3*TS+14,4);ctx.fillStyle='#a85143';ctx.fillRect(x+5,y+5,3*TS-10,63);ctx.fillStyle='#8c4039';ctx.beginPath();ctx.moveTo(x-3,y+10);ctx.lineTo(x+TS*1.5,y-22);ctx.lineTo(x+TS*3+3,y+10);ctx.closePath();ctx.fill();ctx.fillStyle='#bd6350';ctx.fillRect(x+14,y+16,116,48);ctx.fillStyle='#e2b886';ctx.fillRect(x+22,y+26,26,38);ctx.fillRect(x+94,y+26,26,38);ctx.fillStyle='#a85143';ctx.fillRect(x+54,y+31,43,33);ctx.fillStyle='#dca27c';ctx.fillRect(x+58,y+36,35,28);ctx.fillStyle='#6d4d3e';ctx.fillRect(x+73,y+43,2,21);ctx.fillStyle='#f0d47a';ctx.fillRect(x+27,y+30,16,20);ctx.fillRect(x+99,y+30,16,20);ctx.strokeStyle='#8e6247';ctx.lineWidth=2;ctx.strokeRect(x+27,y+30,16,20);ctx.strokeRect(x+99,y+30,16,20);ctx.fillStyle='#f5e6be';ctx.fillRect(x+62,y+66,26,8);ctx.fillStyle='#6c8450';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('MOONROOT',x+74,y+78);}

  function drawTree(x,y,scale=1){const px=x*TS,py=y*TS;ctx.fillStyle='#755b42';ctx.fillRect(px+20*scale,py+27*scale,8*scale,17*scale);ctx.fillStyle='#508051';ctx.beginPath();ctx.arc(px+22*scale,py+20*scale,17*scale,0,Math.PI*2);ctx.arc(px+34*scale,py+24*scale,12*scale,0,Math.PI*2);ctx.arc(px+13*scale,py+28*scale,11*scale,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6b9b5b';ctx.beginPath();ctx.arc(px+17*scale,py+15*scale,10*scale,0,Math.PI*2);ctx.arc(px+30*scale,py+18*scale,8*scale,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9fbd73';ctx.fillRect(px+12*scale,py+12*scale,3*scale,2*scale);}
  function drawDecor(){[[10,1,1],[13,1,.85],[17,1,1],[1,5,.9],[1,8,.75],[11,2,.8],[18,10,1],[1,10,.8],[7,11,.8],[15,10,.95]].forEach(a=>drawTree(...a));for(let i=0;i<6;i++){const x=9+(i*3)%10,y=1+(i*5)%10;if(!isPath(x,y)&&!isBarnTile(x,y))drawFlower(x*TS+10+(i%3)*7,y*TS+12+(i%2)*9,i);}}
  function drawFlower(x,y,i){ctx.fillStyle='#477849';ctx.fillRect(x,y+3,2,7);ctx.fillStyle=['#f5e1a3','#f5c5b7','#e8eff2'][i%3];ctx.fillRect(x-2,y,3,3);ctx.fillRect(x+2,y,3,3);ctx.fillRect(x,y-2,3,3);ctx.fillRect(x,y+2,3,3);ctx.fillStyle='#e6bb50';ctx.fillRect(x,y,2,2);}
  function drawTower(t){const x=t.x*TS,y=t.y*TS;ctx.fillStyle='#437b51';ctx.beginPath();ctx.ellipse(x,y+13,17,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#714d35';ctx.fillRect(x-3,y-2,6,16);ctx.fillStyle='#7fae5c';ctx.beginPath();ctx.arc(x,y-5,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a5cd76';ctx.fillRect(x-6,y-9,12,5);ctx.fillStyle='#e7d875';ctx.fillRect(x-2,y-14,4,4);if(t.flash>0){ctx.strokeStyle=`rgba(242,222,128,${t.flash})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y-6,14+t.flash*8,0,Math.PI*2);ctx.stroke();}}
  function drawPlayer(){const p=state.player,x=p.x*TS,y=p.y*TS;ctx.fillStyle='#31533b45';ctx.beginPath();ctx.ellipse(x,y+12,11,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#496447';ctx.fillRect(x-7,y-5,14,16);ctx.fillStyle='#e9c7a1';ctx.fillRect(x-6,y-13,12,10);ctx.fillStyle='#c97051';ctx.fillRect(x-8,y-16,16,5);ctx.fillRect(x-5,y-20,11,4);ctx.fillStyle='#483c31';ctx.fillRect(x-4+(state.player.face.x*2),y-9+(state.player.face.y*2),2,2);ctx.fillRect(x+2+(state.player.face.x*2),y-9+(state.player.face.y*2),2,2);ctx.fillStyle='#654939';ctx.fillRect(x-7,y+9,5,4);ctx.fillRect(x+2,y+9,5,4);}
  function drawEnemy(e){const x=e.x*TS,y=e.y*TS;ctx.fillStyle='#392d4b44';ctx.beginPath();ctx.ellipse(x,y+9,10,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.hit>0?'#ead6a0':'#554765';ctx.beginPath();ctx.arc(x,y,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#706080';ctx.fillRect(x-8,y-4,16,9);ctx.fillStyle='#d9b970';ctx.fillRect(x-5,y-2,3,3);ctx.fillRect(x+3,y-2,3,3);ctx.fillStyle='#48364f';ctx.fillRect(x-6,y+7,4,4);ctx.fillRect(x+3,y+7,4,4);ctx.fillStyle='#eee4bf';ctx.fillRect(x-4,y-8,3,3);ctx.fillRect(x+3,y-8,3,3);if(e.hp<2){ctx.fillStyle='#432f44';ctx.fillRect(x-10,y-15,20,3);ctx.fillStyle='#e48767';ctx.fillRect(x-10,y-15,10,y?3:3);}}
  function drawScene(){ctx.clearRect(0,0,W,H);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)drawTile(x,y);drawPond();drawGarden();drawPath();drawDecor();drawBarn();for(const t of state.towers)drawTower(t);for(const s of state.shots){ctx.fillStyle='#ffe58a';ctx.beginPath();ctx.arc(s.x*TS,s.y*TS,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff7c9';ctx.fillRect(s.x*TS-1,s.y*TS-1,2,2);}for(const e of state.enemies)drawEnemy(e);drawPlayer();if(state.hover&&state.hover.x>=0&&state.hover.x<COLS&&state.hover.y>=0&&state.hover.y<ROWS){const {x,y}=state.hover;ctx.strokeStyle='rgba(255,255,235,.78)';ctx.lineWidth=2;ctx.strokeRect(x*TS+2,y*TS+2,TS-4,TS-4);if(state.tool==='tower'&&state.phase==='day'){ctx.fillStyle='rgba(83,122,75,.12)';ctx.beginPath();ctx.arc((x+.5)*TS,(y+.5)*TS,TS*3.1,0,Math.PI*2);ctx.fill();}}
    if(state.phase==='night'){ctx.fillStyle='rgba(27,35,73,.43)';ctx.fillRect(0,0,W,H);for(let i=0;i<40;i++){const x=(i*173+31)%W,y=(i*97+21)%250;ctx.fillStyle=`rgba(247,237,180,${.25+rand(i+Math.floor(state.elapsed))*0.5})`;ctx.fillRect(x,y,2,2);}ctx.fillStyle='rgba(255,230,139,.8)';ctx.beginPath();ctx.arc(846,70,19,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(74,83,126,.86)';ctx.beginPath();ctx.arc(855,63,18,0,Math.PI*2);ctx.fill();for(const t of state.towers){const grd=ctx.createRadialGradient(t.x*TS,t.y*TS,3,t.x*TS,t.y*TS,92);grd.addColorStop(0,'rgba(239,218,122,.14)');grd.addColorStop(1,'rgba(239,218,122,0)');ctx.fillStyle=grd;ctx.beginPath();ctx.arc(t.x*TS,t.y*TS,92,0,Math.PI*2);ctx.fill();}}
  }
  function spawnEnemy(){const p=route[0];state.enemies.push({x:p.x,y:p.y,segment:0,speed:.58+state.day*.035,hp:state.day>2?2:1,attack:0,hit:0});state.spawned++;}
  function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
  function updateNight(dt){state.nightAge+=dt;state.spawnTimer-=dt;if(state.spawned<state.waveTotal&&state.spawnTimer<=0){spawnEnemy();state.spawnTimer=Math.max(.82,1.8-state.day*.06);}for(const e of state.enemies){e.hit=Math.max(0,e.hit-dt*3);let move=e.speed*dt;while(move>0&&e.segment<route.length-1){const target=route[e.segment+1],dx=target.x-e.x,dy=target.y-e.y,d=Math.hypot(dx,dy);if(d<=move){e.x=target.x;e.y=target.y;move-=d;e.segment++;}else{e.x+=dx/d*move;e.y+=dy/d*move;move=0;}}if(e.segment>=route.length-1){e.attack+=dt;if(e.attack>=1.15){e.attack=0;state.hp=Math.max(0,state.hp-1);toast('A monster reached the barn!');}}}
    for(const t of state.towers){t.cooldown-=dt;t.flash=Math.max(0,t.flash-dt*3);if(t.cooldown<=0){const target=state.enemies.filter(e=>e.hp>0&&distance(t,e)<3.15).sort((a,b)=>b.segment-a.segment)[0];if(target){state.shots.push({x:t.x,y:t.y-0.18,target,speed:5.7});t.cooldown=.82;t.flash=.8;}}}
    for(const s of state.shots){if(!state.enemies.includes(s.target))continue;const dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy),step=s.speed*dt;if(d<=step+.11){s.target.hp--;s.target.hit=.2;s.target.hurt=0;if(s.target.hp<=0){state.gold+=2;state.enemies=state.enemies.filter(e=>e!==s.target);}s.hit=true;}else{s.x+=dx/d*step;s.y+=dy/d*step;}}state.shots=state.shots.filter(s=>!s.hit&&state.enemies.includes(s.target));if(state.hp<=0){state.dead=true;showModal('lose');}else if(state.spawned>=state.waveTotal&&state.enemies.length===0)finishNight();}
  function update(dt){state.elapsed+=dt;if(state.phase==='day'&&!state.dead){state.dayTime+=dt;if(state.dayTime>=state.dayLength)startNight();}else if(state.phase==='night'&&!state.dead)updateNight(dt);if(state.phase==='day')ui.countdown.textContent=`DUSK IN ${Math.max(0,Math.ceil(state.dayLength-state.dayTime))}s`;ui.enemies.textContent=state.enemies.length;}
  function frame(time){if(!state.lastTime)state.lastTime=time;const dt=Math.min(.05,(time-state.lastTime)/1000);state.lastTime=time;update(dt);drawScene();requestAnimationFrame(frame);}
  selectTool('hoe');updateUI();requestAnimationFrame(frame);
})();

