(() => {
  'use strict';
  const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=960,H=576,TS=48,COLS=20,ROWS=12,$=id=>document.getElementById(id);
  const ui={gold:$('goldLabel'),seeds:$('seedLabel'),hp:$('hpLabel'),day:$('dayLabel'),phase:$('phaseLabel'),icon:$('phaseIcon'),scene:$('sceneTitle'),mission:$('missionTitle'),missionText:$('missionText'),progress:$('progressFill'),progressText:$('progressText'),countdown:$('phaseCountdown'),wave:$('waveLabel'),enemies:$('enemyLabel'),button:$('phaseButton'),tip:$('toolHint'),toast:$('toast'),modal:$('modal')};
  const tools=[{id:'hoe',name:'Hoe',glyph:'⌁',hint:'Till an empty patch in the garden.'},{id:'seed',name:'Seeds',glyph:'✿',hint:'Plant a seed on a tilled patch.'},{id:'water',name:'Water',glyph:'♧',hint:'Water a planted crop to help it grow.'},{id:'harvest',name:'Harvest',glyph:'✂',hint:'Gather crops when they are ready.'},{id:'tower',name:'Turret',glyph:'⌂',hint:'Build on grass for 12 gold. It fires at night.'}];
  const path=[[19,2],[19,3],[18,3],[17,3],[16,3],[16,4],[16,5],[15,5],[14,5],[14,6],[13,6],[13,7],[13,8],[12,8],[11,8],[10,8],[9,8],[9,9],[8,9],[7,9],[6,9],[5,9]],pathSet=new Set(path.map(([x,y])=>`${x},${y}`)),route=path.map(([x,y])=>({x:x+.5,y:y+.5}));
  const garden=(x,y)=>x>=1&&x<=8&&y>=1&&y<=8,key=(x,y)=>`${x},${y}`,isPath=(x,y)=>pathSet.has(key(x,y)),isBarnTile=(x,y)=>x>=2&&x<=4&&y>=9&&y<=10;
  const state={day:1,phase:'day',gold:24,seeds:5,hp:10,maxHp:10,tool:'hoe',crops:new Map(),tilled:new Set(),towers:[],enemies:[],shots:[],player:{x:5.5,y:6.5,face:{x:0,y:1}},hover:null,dayTime:0,dayLength:72,spawned:0,waveTotal:0,spawnTimer:0,nightAge:0,elapsed:0,lastTime:0,dead:false,modalMode:''};
  const toolButtons=new Map(),toolGrid=$('toolGrid');
  tools.forEach((t,i)=>{const b=document.createElement('button');b.type='button';b.className='tool-button';b.dataset.tool=t.id;b.setAttribute('aria-label',`${i+1}: ${t.name}`);b.innerHTML=`<span class="key">${i+1}</span><span class="glyph">${t.glyph}</span><small>${t.name}</small>`;b.addEventListener('click',()=>selectTool(t.id));toolGrid.appendChild(b);toolButtons.set(t.id,b);});
  let toastTimer;function toast(m){ui.toast.textContent=m;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100);}
  function selectTool(id){state.tool=id;toolButtons.forEach((b,k)=>b.classList.toggle('active',k===id));ui.tip.textContent=tools.find(t=>t.id===id).hint;}
  function tileAtEvent(e){const r=canvas.getBoundingClientRect();return{x:Math.floor((e.clientX-r.left)*W/r.width/TS),y:Math.floor((e.clientY-r.top)*H/r.height/TS)};}
  function useTile(x,y){if(x<0||x>=COLS||y<0||y>=ROWS||state.dead)return;const k=key(x,y),crop=state.crops.get(k),tool=state.tool;
    if(tool==='hoe'){if(state.phase!=='day'){toast('The garden can wait until morning.');return;}if(!garden(x,y)||isPath(x,y)||crop){toast('Choose an empty patch inside the garden.');return;}if(state.tilled.has(k)){toast('This patch is ready for a seed.');return;}state.tilled.add(k);toast('Fresh earth, ready for planting!');}
    else if(tool==='seed'){if(state.phase!=='day'){toast('Planting is a daytime job.');return;}if(!state.tilled.has(k)||crop){toast('Till a patch first, then plant here.');return;}if(state.seeds<1){toast('You are out of seeds.');return;}state.seeds--;state.crops.set(k,{growth:0,watered:false});toast('A little seed tucked into the soil.');}
    else if(tool==='water'){if(state.phase!=='day'){toast('Water the crops in the morning.');return;}if(!crop){toast('There is no crop to water here.');return;}if(crop.watered){toast('This crop has had its drink today.');return;}crop.watered=true;toast('Your crop looks refreshed.');}
    else if(tool==='harvest'){if(!crop||crop.growth<3){toast('Not quite ripe yet.');return;}state.crops.delete(k);state.tilled.add(k);state.gold+=8;state.seeds++;toast('Harvested! +8 gold and a seed.');}
    else if(tool==='tower'){if(state.towers.some(t=>t.x===x+.5&&t.y===y+.5)){toast('There is already a turret here.');return;}if(isPath(x,y)||garden(x,y)||isBarnTile(x,y)){toast('Turrets need a clear patch of meadow.');return;}if(state.gold<12){toast('A sprout turret costs 12 gold.');return;}state.gold-=12;state.towers.push({x:x+.5,y:y+.5,cooldown:.2,flash:0});toast('Sprout turret planted. It will guard your barn!');}
    updateUI();
  }
