  canvas.addEventListener('pointermove',e=>state.hover=tileAtEvent(e));canvas.addEventListener('pointerleave',()=>state.hover=null);canvas.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;const p=tileAtEvent(e);useTile(p.x,p.y);});
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if('12345'.includes(k))selectTool(tools[Number(k)-1].id);else if(k==='w'||k==='arrowup')tryMove(0,-1);else if(k==='s'||k==='arrowdown')tryMove(0,1);else if(k==='a'||k==='arrowleft')tryMove(-1,0);else if(k==='d'||k==='arrowright')tryMove(1,0);else if(k===' ')useFacing();else if(k==='enter'){if(!ui.modal.hidden)modalAction();else if(state.phase==='day')startNight();}});
  ui.button.addEventListener('click',()=>state.phase==='day'?startNight():toast('Your turrets are on night watch!'));$('modalButton').addEventListener('click',modalAction);
