  function finishNight(){if(state.dead)return;state.gold+=Math.max(2,Math.floor(state.waveTotal/2));showModal('win');}
  function dawn(){state.day++;state.phase='day';state.dayTime=0;state.enemies=[];state.shots=[];state.towers.forEach(t=>t.cooldown=.2);for(const c of state.crops.values()){if(c.watered)c.growth=Math.min(3,c.growth+1);c.watered=false;}state.seeds+=2;state.player.x=5.5;state.player.y=6.5;state.player.face={x:0,y:1};ui.scene.textContent='The farm wakes with the sun';updateUI();toast('A new morning! +2 seeds.');}
  function showModal(mode){state.modalMode=mode;const data={win:['✦','NIGHT CLEARED','The barn is safe!','The monsters scattered into the woods. Your crops have had a chance to grow.','Welcome the morning'],lose:['♡','THE NIGHT GOT TOO WILD','The barn needs mending','The monsters broke through. Start a fresh farm and try a few more turrets.','Start a new farm']}[mode];$('modalIcon').textContent=data[0];$('modalEyebrow').textContent=data[1];$('modalTitle').textContent=data[2];$('modalText').textContent=data[3];$('modalButton').innerHTML=`${data[4]} <span>→</span>`;ui.modal.hidden=false;}
  function modalAction(){ui.modal.hidden=true;if(state.modalMode==='win')dawn();else if(state.modalMode==='lose')resetGame();state.modalMode='';}
  function resetGame(){state.day=1;state.phase='day';state.gold=24;state.seeds=5;state.hp=10;state.towers=[];state.crops.clear();state.tilled.clear();state.enemies=[];state.shots=[];state.dead=false;state.dayTime=0;state.player.x=5.5;state.player.y=6.5;ui.scene.textContent='A bright new morning';updateUI();}
  function updateUI(){const night=state.phase==='night',ready=[...state.crops.values()].filter(c=>c.growth>=3).length,planted=state.crops.size;ui.gold.textContent=state.gold;ui.seeds.textContent=state.seeds;ui.hp.textContent=`${state.hp} / ${state.maxHp}`;ui.day.innerHTML=`Day ${state.day} <i>·</i> Spring`;ui.phase.textContent=night?'NIGHT WATCH':'DAYTIME';ui.icon.textContent=night?'☾':'☀';ui.icon.style.color=night?'#8795d6':'#e3a739';ui.icon.style.background=night?'#eaebfa':'#fff3d5';ui.button.innerHTML=night?'<span>☾</span> Night watch in progress <kbd>● LIVE</kbd>':'<span>☀</span> Finish the day <kbd>Enter</kbd>';ui.button.disabled=night;ui.wave.textContent=state.day;ui.enemies.textContent=state.enemies.length;ui.progress.style.width=`${Math.min(3,planted)/3*100}%`;ui.progressText.textContent=`${Math.min(3,planted)} / 3 crops`;if(planted>=3){ui.mission.textContent=ready?'Harvest your ripe crop':'Keep your crops growing';ui.missionText.textContent=ready?`${ready} crop${ready>1?'s are':' is'} ready to harvest. Turn harvests into gold and seeds.`:'Water your crops each morning and keep the barn protected after dark.';}else{ui.mission.textContent='Plant the first seeds';ui.missionText.textContent='Till a patch, plant seeds, and give them a drink before dusk.';}if(night){ui.countdown.textContent=`${state.enemies.length} ON THE PATH`;ui.countdown.style.color='#7880bb';}else{ui.countdown.textContent=`DUSK IN ${Math.max(0,Math.ceil(state.dayLength-state.dayTime))}s`;ui.countdown.style.color='#bc9560';}}
